package com.printflow.files;
import org.apache.pdfbox.pdmodel.*;import org.apache.pdfbox.pdmodel.common.*;import org.apache.pdfbox.pdmodel.graphics.image.*;import org.apache.pdfbox.pdmodel.font.*;import org.apache.pdfbox.pdmodel.interactive.annotation.*;import java.io.*;import java.util.*;
/** Bounded child JVM; writes a separate, sanitized source review copy with numbered comment markers. */
public final class ReferenceReviewWorker {
 private static final class Copies extends org.apache.pdfbox.multipdf.PDFCloneUtility {Copies(PDDocument doc){super(doc);}}
 @SuppressWarnings("unchecked") public static void main(String[] args){try(var out=new PDDocument()){
  if(args[1].equals("application/pdf")){try(var source=org.apache.pdfbox.Loader.loadPDF(new File(args[0]),org.apache.pdfbox.io.IOUtils.createTempFileOnlyStreamCache())){if(source.isEncrypted()||source.getNumberOfPages()>100)throw new IOException();for(var page:source.getPages()){var copied=out.importPage(page);if(page.getResources()!=null)copied.setResources(new PDResources((org.apache.pdfbox.cos.COSDictionary)new Copies(out).cloneForNewDocument(page.getResources().getCOSObject())));copied.setAnnotations(new ArrayList<>());copied.getCOSObject().removeItem(org.apache.pdfbox.cos.COSName.AA);}}}
  else{try(var input=javax.imageio.ImageIO.createImageInputStream(new File(args[0]))){var readers=javax.imageio.ImageIO.getImageReaders(input);if(!readers.hasNext())throw new IOException();var reader=readers.next();try{reader.setInput(input);if((long)reader.getWidth(0)*reader.getHeight(0)>25000000L)throw new IOException();}finally{reader.dispose();}}var image=PDImageXObject.createFromByteArray(out,java.nio.file.Files.readAllBytes(java.nio.file.Path.of(args[0])),"reference");var page=new PDPage(new PDRectangle(image.getWidth(),image.getHeight()));out.addPage(page);try(var canvas=new PDPageContentStream(out,page)){canvas.drawImage(image,0,0,image.getWidth(),image.getHeight());}}
  var job=new tools.jackson.databind.json.JsonMapper().readValue(java.nio.file.Files.readString(java.nio.file.Path.of(args[2])),Map.class);var pins=(List<Map<String,Object>>)job.get("pins");int index=0;for(var pin:pins){index++;int n=((Number)pin.get("page")).intValue();var page=out.getPage(n-1);var box=page.getCropBox();float u=((Number)pin.get("x")).floatValue(),v=((Number)pin.get("y")).floatValue(),w=box.getWidth(),h=box.getHeight(),x,y;switch(Math.floorMod(page.getRotation(),360)){case 90:x=v*w;y=u*h;break;case 180:x=(1-u)*w;y=v*h;break;case 270:x=(1-v)*w;y=(1-u)*h;break;default:x=u*w;y=(1-v)*h;}x+=box.getLowerLeftX();y+=box.getLowerLeftY();try(var c=new PDPageContentStream(out,page,PDPageContentStream.AppendMode.APPEND,true,true)){c.setNonStrokingColor(java.awt.Color.RED);c.addRect(x-7,y-7,18,18);c.fill();c.beginText();c.setNonStrokingColor(java.awt.Color.WHITE);c.setFont(new PDType1Font(Standard14Fonts.FontName.HELVETICA_BOLD),10);c.newLineAtOffset(x-4,y-3);c.showText(Integer.toString(index));c.endText();}var note=new PDAnnotationText();note.setRectangle(new PDRectangle(x-7,y-7,18,18));note.setContents(index+". "+pin.get("text"));page.getAnnotations().add(note);}
  out.getDocumentInformation().setTitle("Artwork review copy — original unchanged");out.save(args[3]);
 }catch(Throwable bad){System.exit(2);}}
}
